from scipy.optimize import least_squares
g = sigma - 31.4*eps*np.exp(-0.756*eps)/T
forms={
 'bose 1/(exp(k/T)-1)': lambda t,k,q: 1/(np.exp(k/t)-1),
 'einstein (k/T)^2 e/(e-1)^2': lambda t,k,q: (k/t)**2*np.exp(k/t)/(np.exp(k/t)-1)**2,
 'bose 1/(exp(k*T)-1)': lambda t,k,q: 1/(np.exp(k*t)-1),
 'exp(-k/T)*T^q': lambda t,k,q: np.exp(-k/t)*t**q,
 'exp(-k*T^2)*T^q': lambda t,k,q: np.exp(-k*t**2)*t**q,
}
base=lambda t: np.column_stack([np.ones_like(t),t,t**2,1/t])
for nm,f in forms.items():
    def resid(p):
        A=np.column_stack([base(T), f(T,p[0],p[1])])
        c,*_=np.linalg.lstsq(A,g,rcond=None)
        return g-A@c
    best=None
    for s in [(0.5,0),(1,1),(2,0.5),(0.2,2),(3,0),(0.1,0.5)]:
        try:
            r_=least_squares(resid,s,xtol=1e-15,ftol=1e-15,gtol=1e-15)
            if best is None or r_.cost<best.cost: best=r_
        except Exception: pass
    if best is not None:
        print(nm, "%.3e"%(np.mean(best.fun**2)/np.var(g)), np.round(best.x,5))
